arguments.command:
python3 -c "
import csv, ast

emp = {}
with open('employees.csv') as f:
    for row in csv.DictReader(f):
        emp[row['PESEL']] = row

tasks = {}
with open('tasks.csv') as f:
    for row in csv.DictReader(f):
        tasks[row['task_id']] = row

rows = []
with open('timesheet.csv') as f:
    rows = list(csv.DictReader(f))

print('num timesheet rows', len(rows))
print('num employees', len(emp))
print('num tasks', len(tasks))

# check employee ids not in emp
missing_emp = set()
for r in rows:
    if r['employee_id'] not in emp:
        missing_emp.add(r['employee_id'])
print('missing employee ids:', missing_emp)

# check task ids not in tasks
missing_task = set()
for r in rows:
    try:
        pt = ast.literal_eval(r['performed_tasks']) if r['performed_tasks'] else []
    except Exception as e:
        print('parse error', r, e)
        continue
    for t in pt:
        if str(t) not in tasks:
            missing_task.add(t)
print('missing task ids:', missing_task)
"

