    for row in csv.DictReader(f):
        emp.append(row['PESEL'])

missing = ['68011910138', '16102016795', '62020111425', '15720759071', '84731091580']

def dist(a,b):
    return sum(1 for i in range(11) if a[i]!=b[i])

for m in missing:
    ds = sorted(((dist(m,e), e) for e in emp))
